'use strict';
const ROLE={doctor:{name:'Doctor / prescriber',person:'Team member',initial:'TM',icon:'clinical',desc:'Consult, document, prescribe and refer'},nurse:{name:'Nurse / clinician',person:'Team member',initial:'TM',icon:'heart',desc:'Assess, record observations and collect samples'},care:{name:'Care professional',person:'Team member',initial:'TM',icon:'care',desc:'Care plans, visit notes and escalations'},wellbeing:{name:'Wellbeing practitioner',person:'Team member',initial:'TM',icon:'leaf',desc:'Sessions, goals and progress notes'},manager:{name:'Clinical manager',person:'Team member',initial:'TM',icon:'shield',desc:'Oversight, allocation, incidents and audit'},admin:{name:'Reception / operations',person:'Team member',initial:'TM',icon:'calendar',desc:'Scheduling, demographics and payment status'}};
const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M5 3v4 M19 3v4 M3 9h18 M4 5h16v16H4z M8 13h2 M14 13h2',people:'M14 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M2 22v-5a7 7 0 0 1 14 0v5 M17 3a4 4 0 0 1 0 8 M18 14a5 5 0 0 1 4 5v3',clinical:'M5 3v5a5 5 0 0 0 10 0V3 M3 3h4 M13 3h4 M10 13v2a5 5 0 0 0 10 0v-3 M22 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h6',rx:'M5 21V3h7a4 4 0 0 1 0 8H5 M10 11l10 10 M19 11l-9 10',lab:'M9 3h6 M10 3v7l-6 9q-1 2 2 2h12q3 0 2-2l-6-9V3 M8 15h8',message:'M21 4H3v14h5l4 3v-3h9z M7 9h10 M7 13h6',task:'M9 3h6v4H9z M8 5H4v17h16V5h-4 M8 12l2 2 5-5 M8 18h8',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-4 10 3 3 5-6',heart:'m12 21-9-9C-2 3 8-1 12 6 16-1 26 3 21 12z',care:'M3 12h4l2-5 4 11 3-6h5',leaf:'M4 20c14 2 17-8 16-17C11 2 2 5 4 16 M4 20l11-11',arrow:'M4 12h16 m-6-6 6 6-6 6',plus:'M12 4v16 M4 12h16',check:'m5 12 4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0 m-2 5 6 6',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4',video:'M3 5h12v14H3z m12 5 7-4v12l-7-4',settings:'M4 7h16 M4 17h16 M9 4v6 M16 14v6',bell:'M6 9a6 6 0 0 1 12 0v7l2 3H4l2-3z M10 22h4',log:'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h5',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7v.1'};
const ico=k=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.file}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PATIENTS=(typeof window!=='undefined'&&window.LIFECOME_PATIENTS)||[];
const blankRecord=()=>({note:{subjective:'Patient describes their current concern and expectations.',objective:'Observations and examination findings to be recorded following assessment.',assessment:'Clinical assessment to be completed by the responsible clinician.',plan:'Agree investigations, treatment options and follow-up with the patient.',safety:'Explain when and how to seek further help; confirm understanding.',consent:'Discussed consultation format and information sharing.',share:'Patient summary only'},signed:false,signedAt:null,addenda:[],rx:null,rxStatus:'Not started',order:null,sample:'Not collected',resultReviewed:false,resultReleased:false,resultAction:null,referral:null,referralSent:false,careNote:null,wellbeingNote:null,summaryReleased:false,messages:[],tasks:[],incidents:[],consent:null});
const defaults=()=>({role:'doctor',patient:0,records:PATIENTS.map(blankRecord),events:[],appointments:[],taskDone:false,settings:{channel:'In-app',text:'Standard'},notification:false});
let state=defaults(),current='dashboard',dirty=false,formError='';const KEY='lifecome-professional-demo-v1';
try{let old=JSON.parse(sessionStorage.getItem(KEY)||'null');if(old?.records?.length===PATIENTS.length&&ROLE[old.role])state=old;}catch(_){}
const params=typeof location!=='undefined'?new URLSearchParams(location.search):new URLSearchParams();const USER=typeof window!=='undefined'&&window.LIFECOME_USER?window.LIFECOME_USER:null;if(USER&&ROLE[USER.role])state.role=USER.role;
const p=()=>PATIENTS[state.patient],r=()=>state.records[state.patient],who=()=>USER?{...ROLE[state.role],person:USER.name,initial:USER.name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}:ROLE[state.role];
const save=()=>{try{sessionStorage.setItem(KEY,JSON.stringify(state));}catch(_){}};
const now=()=>new Date().toLocaleString('en-GB',{timeZone:'Europe/London',dateStyle:'medium',timeStyle:'short'});
function audit(action){state.events.unshift({action,patient:p().id,actor:who().person,role:who().name,time:now()});save();}
const tag=(s,c='')=>`<span class="tag ${c}">${esc(s)}</span>`;
const link=(text,to,style='secondary',icon='')=>`<a class="btn ${style}" href="#${to}">${icon?ico(icon):''}${text}</a>`;
const button=(text,action,style='',extra='')=>`<button class="btn ${style}" type="button" data-action="${action}" ${extra}>${text}</button>`;
const head=(h,sub,actions='',eye='WORKSPACE')=>`<div class="pagehead"><div><div class="eyebrow">${eye}</div><h1>${h}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`;
const card=(title,body,right='')=>`<section class="card"><header class="card-head"><h2>${title}</h2>${right}</header><div class="card-body">${body}</div></section>`;
const banner=(text,c='')=>`<div class="banner ${c}">${ico(c==='red'?'shield':'info')}<span>${text}</span></div>`;
const detail=arr=>arr.map(([a,b])=>`<div class="detail"><span>${a}</span><strong>${b}</strong></div>`).join('');
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}" type="${type}" required ${extra}></label>`;
const area=(label,name,value='',required=true)=>`<label class="field"><span>${label}</span><textarea name="${name}" ${required?'required':''} rows="3">${esc(value)}</textarea></label>`;
const select=(label,name,options,value='')=>`<label class="field"><span>${label}</span><select name="${name}" required>${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
const check=(label,name,required=true)=>`<label class="check"><input type="checkbox" name="${name}" ${required?'required':''}><span>${label}</span></label>`;
const form=(name,body,label='Save and continue',cancel='dashboard')=>`<form data-form="${name}">${formError?`<div class="formerror" role="alert">${esc(formError)}</div>`:''}${body}<div class="footer-actions">${link('Back',cancel,'ghost')}<button class="btn" type="submit">${label}${ico('arrow')}</button></div></form>`;
const row=(title,sub,to,color='blue')=>`<div class="row"><span class="task-dot ${color}"></span><div class="grow"><strong>${title}</strong><small>${sub}</small></div><a href="#${to}" aria-label="Open ${title}">${ico('arrow')}</a></div>`;
const patientCell=(x)=>`<div class="patient-cell"><span class="avatar ${x.id.endsWith('2')?'green':''}">${x.initial}</span><span><strong>${x.name}</strong><small>${x.id}</small></span></div>`;
const table=(cols,rows)=>`<div class="table-wrap"><table><thead><tr>${cols.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr>${x.map(y=>`<td>${y}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const patientBar=()=>`<div class="patientbar"><span class="avatar">${p().initial}</span><div><h2>${p().name}</h2><small>${p().id} &nbsp; · &nbsp; DOB ${p().dob} &nbsp; · &nbsp; ${p().age} years</small></div><div class="tags">${state.role!=='admin'?tag(p().allergy,'amber'):tag(p().funding,'blue')}</div></div>`;
const patientTabs=()=>`<div class="tabs">${[['patient','Overview'],['history','History'],['consultation','Consultation'],['notes','Notes'],['medications','Medicines'],['results','Results'],['documents','Documents'],['consent','Consent']].filter(([k])=>allowed(k)).map(([k,l])=>`<a href="#${k}" class="${current===k?'active':''}">${l}</a>`).join('')}</div>`;
const clinicalTop=(h,s,actions='')=>head(h,s,actions,'PATIENT WORKSPACE')+patientBar()+patientTabs();
const ALL=['doctor','nurse','care','wellbeing','manager','admin'],CLIN=['doctor','nurse','manager'];
const routes={};function add(key,title,group,roles,render,desc=''){routes[key]={key,title,group,roles,render,description:desc||title};}
const greeting=()=>{const h=Number(new Date().toLocaleString('en-GB',{hour:'2-digit',hour12:false,timeZone:'Europe/London'}));return h<12?'Good morning':h<18?'Good afternoon':'Good evening';};const today=()=>new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/London'});
const emptyState=()=>`<div class="card"><div class="card-body empty">${ico('people')}<h2>No patient records yet</h2><p class="sub">Patients appear here once they are registered with LifeCome Health.</p></div></div>`;const safeRender=page=>{try{return page.render();}catch(_){return emptyState();}};
const allowed=k=>routes[k]?.roles.includes(state.role);
function welcome(){return `<div class="welcome"><div class="welcome-intro"><div class="brand"><span class="lc-logo on-dark sm" role="img" aria-label="LifeCome Health"><img src="/brand/lifecome-health-mark.svg" alt="" width="34" height="32"><span class="lc-word"><b>Life</b><b>Come</b><b>Health</b></span></span><small>PROFESSIONAL PORTAL</small></div><h1>Connected care.<br>Clear decisions.<br>One patient record.</h1><p>A considered workspace for the people behind every appointment, result and moment of care.</p></div><div class="welcome-content"><div class="eyebrow">EXPLORE THE WORKSPACE</div><h1>Choose your professional role</h1><p class="sub">Each role opens a different view of the same connected record.</p><div class="rolegrid">${Object.entries(ROLE).map(([k,v])=>`<button class="rolecard" data-role="${k}">${ico(v.icon)}<strong>${v.name}</strong><small>${v.desc}</small></button>`).join('')}</div></div></div>`;}
const stats=arr=>`<div class="metrics">${arr.map(([label,num,sub,icon])=>`<div class="metric">${ico(icon)}<small>${label}</small><strong>${num}</strong><span>${sub}</span></div>`).join('')}</div>`;
add('dashboard','Today’s overview','Workspace',ALL,()=>{
 const clinical=['doctor','nurse','manager'].includes(state.role),care=state.role==='care',well=state.role==='wellbeing',admin=state.role==='admin';
 const workload=care?'Care visits':well?'Wellbeing sessions':'Appointments';
 return head(`${greeting()}, ${who().person.split(' ')[0]}.`,today()+' · Your day, clearly organised.',link('View schedule','schedule','secondary','calendar'),'TODAY AT LIFECOME')+stats([[workload,String(PATIENTS.length),'Scheduled today','calendar'],[clinical?'Results to review':'Follow-ups','0',clinical?'Nothing waiting':'Assigned to your team','lab'],['Open tasks','0','Across your workspace','task'],['Records completed',state.records.filter(x=>x.signed).length,'This session','file']])+`<div class="grid"><div><section class="card"><header class="card-head"><h2>Today’s ${workload.toLowerCase()}</h2>${tag(new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'Europe/London'}),'gray')}</header>${table(['Time','Patient','Service','Status',''],PATIENTS.map((x,i)=>[x.time,patientCell(x),care?'Care visit':well?'Wellbeing review':x.service,tag(state.records[i].appointmentCancelled?'Cancelled':state.records[i].arrived?'Arrived':x.status,state.records[i].appointmentCancelled?'red':i===0?'green':'gray'),`<button class="btn secondary" data-patient="${i}" data-target="${admin?'appointment':care?'care-visit':well?'wellbeing-session':'patient'}">Open</button>`]))}</section>${card('Your next steps',row('Complete the patient record','Notes, agreed actions and follow-up',clinical?'consultation':care?'care-visit':well?'wellbeing-session':'appointment')+row('Check outstanding work','Tasks assigned to you and your team','tasks','green'))}</div><div>${card('Needs your attention',row('Nothing needs your attention','You’re all caught up','tasks'),tag('Today','amber'))}${card('One connected record',`<p class="sub">See how approved information appears in the patient app.</p>${link('Open patient-view preview','patient-preview','secondary','people')}<p class="audit">Only released records appear in the shared patient view.</p>`)}${card('Your workspace',detail([['Role',who().name],['Location','LifeCome clinic']]))}</div></div>`;
});
add('schedule','Appointments','Workspace',ALL,()=>head('Appointments','Coordinate online, clinic and community appointments.',link('New appointment','appointment-new','','plus'))+`<section class="card"><div class="filter"><div class="pillbar">${tag(new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/London'}).replace(' ',' · '),'blue')}${tag('Schedule','gray')}</div><input class="search" data-search-table placeholder="Search patients or services" aria-label="Search appointments"></div>${table(['Time','Patient','Service','Location','Status',''],[...PATIENTS.map((x,i)=>[x.time,patientCell(x),x.service,x.location,tag(state.records[i].appointmentCancelled?'Cancelled':state.records[i].arrived?'Arrived':x.status,state.records[i].appointmentCancelled?'red':'green'),`<button class="btn secondary" data-patient="${i}" data-target="appointment">View</button>`]),...state.appointments.map(x=>[esc(x.time),patientCell(PATIENTS[x.patient]),esc(x.service),esc(x.location),tag('Request','blue'),link('View','appointment')])])}</section>`);
add('appointment','Appointment details','Workspace',ALL,()=>head('Appointment details','Preparation, attendance and the next clinical step.',link('Back to schedule','schedule'))+patientBar()+`<div class="grid">${card('Appointment',detail([['Service',p().service],['Date','9 November 2026'],['Time',p().time+' · UK time'],['Location',p().location],['Assigned professional',who().person],['Funding',p().funding]])+`<div class="actions" style="margin-top:22px">${state.role==='admin'?button('Mark arrived','arrived'):link('Open workspace',state.role==='care'?'care-visit':state.role==='wellbeing'?'wellbeing-session':'consultation','','arrow')}${link('Reschedule','appointment-new')}${link('Cancel appointment','appointment-cancel','danger')}</div>`)}${card('Before the appointment',banner('Confirm patient identity, contact preferences and appointment suitability.'))}</div>`);
add('appointment-new','Create / reschedule appointment','Workspace',ALL,()=>head('Arrange an appointment','Request an appointment time for this patient.')+card('Appointment request',form('appointment',`<div class="fields">${select('Service','service',['GP consultation','Menopause review','Tests and Health Checks','Paid Sexual Health Check','Professional care','Wellbeing session'])}${select('Location','location',['Online','Clinic','Home visit'])}${field('Date','date','2026-11-10','date')}${field('Time','time','10:30','time')}</div>${select('Funding route','funding',['Self-pay','Membership check pending','Employer benefit check pending','Insurance authorisation pending'])}${check('I have checked the patient and appointment details.','verified')}`,'Save request','schedule')));
add('appointment-cancel','Cancel appointment','Workspace',ALL,()=>head('Cancel appointment','Record the reason and agree the next step.')+patientBar()+card('Cancellation review',form('cancel-appointment',select('Reason','reason',['Patient request','Clinician unavailable','Rebook required'])+area('Follow-up arrangements','followup','Contact the patient to agree a suitable alternative.')+check('Confirm cancellation of this appointment.','confirm'),'Confirm cancellation','appointment')));
add('patients','Patient directory','Workspace',ALL,()=>head('Patient directory','Find a patient and open the appropriate record.')+`<section class="card"><div class="filter"><input class="search" data-search-table placeholder="Search name or patient ID" aria-label="Search patient directory">${tag('3 patients','gray')}</div>${table(['Patient','Date of birth','Service','Contact preference',''],PATIENTS.map((x,i)=>[patientCell(x),x.dob,x.service,x.contact,`<button class="btn secondary" data-patient="${i}" data-target="${state.role==='admin'?'demographics':'patient'}">Open record</button>`]))}</section>`);
add('demographics','Patient details','Patient record',ALL,()=>head('Patient details','Contact details and administrative information.')+patientBar()+card('Identity and contact',detail([['Full name',p().name],['Date of birth',p().dob],['Patient identifier',p().id],['Phone',p().phone],['Email',p().email],['Contact preference',p().contact],['Record status','Patient']]))+banner('Administrative access does not reveal clinical notes, prescriptions or sensitive test results.'));
add('patient','Patient overview','Patient record',['doctor','nurse','care','wellbeing','manager'],()=>clinicalTop('Patient overview','The right information, in one place.',link('Patient app preview','patient-preview'))+`<div class="grid"><div>${card('Current care',row(p().reason,'Appointment · '+p().time,state.role==='care'?'care-plan':state.role==='wellbeing'?'wellbeing-plan':'consultation')+row('Records and documents',r().signed?'Signed consultation note available':'Consultation note awaiting completion','documents','green'))}${card('Record timeline',`<div class="timeline"><div class="event"><strong>Appointment prepared</strong><small>9 November 2026 · Care coordination</small><p>Patient identity and contact details await confirmation.</p></div>${r().signed?`<div class="event"><strong>Consultation signed</strong><small>${esc(r().signedAt)}</small><p>Signed note preserved; amendments require an addendum.</p></div>`:''}<div class="event"><strong>Patient profile created</strong><small>Historical event</small><p>Shared identity for GP, tests, care and wellbeing.</p></div></div>`)}</div><div>${card('Safety and preferences',banner(esc(p().allergy)+' · '+esc(p().allergyStatus),'amber')+detail([['Contact',p().contact],['Sharing consent',r().consent?'Recorded':'Review required'],['Assigned team','LifeCome clinical team']]))}${card('Quick actions',`<div class="actions">${CLIN.includes(state.role)?link('Record observations','observations'):''}${link('Review consent','consent')}${link('Add task','task-new')}</div>`)}</div></div>`);
add('history','Clinical history','Patient record',CLIN,()=>clinicalTop('Clinical history','Review and reconcile the record with the patient.')+`<div class="grid">${card('History summary',detail([['Presenting concern',p().reason],['Medical history','History; to be reconciled'],['Surgical history','To be confirmed at consultation'],['Family history','To be discussed where relevant'],['Social history','Record only information relevant to care']]))}${card('Allergies and medicines',banner(esc(p().allergy),'amber')+row('Medication reconciliation','Review current, recent and non-prescribed medicines','medications')+row('Consent and communication','Confirm preferences and information sharing','consent','green'))}</div>`);
add('consent','Consent & information sharing','Patient record',['doctor','nurse','care','wellbeing','manager'],()=>clinicalTop('Consent & information sharing','Record the discussion, scope and patient preferences.')+card('Consent record',form('consent',select('Decision','decision',['Agreed after discussion','Declined','Further discussion required'])+select('Scope','scope',['Share care summary with usual GP','Laboratory processing for agreed tests','Care-team information sharing','Patient summary release'])+area('Discussion and limitations','discussion',r().consent?.discussion||'Explain the purpose, recipient and information involved; record the patient’s decision.')+select('Discreet notification','channel',['In-app only','Neutral email','Neutral SMS'])+check('The decision and any limitations have been recorded accurately.','confirmed'),'Save consent record','patient')));
add('observations','Record observations','Clinical workspace',['doctor','nurse'],()=>clinicalTop('Record observations','Capture measured findings with time and context.')+card('Observations',form('observations',`<div class="fields">${field('Observation date and time','time','2026-11-09T09:35','datetime-local')}${field('Blood pressure (mmHg)','bp','120/80')}${field('Pulse (beats/minute)','pulse','72','number','min="1" max="300"')}${field('Temperature (°C)','temperature','36.7','number','step="0.1" min="25" max="45"')}</div>${area('Measurement context / other observations','context','Record equipment, technique and clinical context.')}${check('I confirm these observations are accurate.','demo')}`,'Save observations','patient')));
add('consultation','Consultation workspace','Clinical workspace',['doctor','nurse'],()=>clinicalTop('Consultation workspace','Document the encounter and organise the next steps.',tag(r().signed?'Signed':'In progress',r().signed?'green':'blue'))+`<div class="grid"><div>${card('Encounter checks',form('encounter',check('Patient identity and current location confirmed.','identity')+check('Consent and suitability for the consultation format reviewed.','consent')+check('Allergy and medication history reviewed; uncertainties documented.','history')+area('Consultation context','context',r().encounter?.context||'Consultation. Confirm the reason for attendance and patient expectations.'),'Open consultation notes','patient'))}${card('Consultation tools',`<div class="actions">${link('Video room','video')}${link('Observations','observations')}${link('Clinical notes','notes')}${state.role==='doctor'?link('Prescribing','prescriptions'):''}${link('Order tests','test-order')}${state.role==='doctor'?link('Referral','referral-new'):''}</div>`)}</div><div>${card('Patient safety',banner(esc(p().allergy),'amber')+detail([['Identity','Confirm with patient'],['Usual GP','Details and consent to verify'],['Contact preference',p().contact]]))}${card('Encounter progress',row('Clinical note',r().signed?'Signed and locked':'Draft in progress','notes')+row('Patient summary',r().summaryReleased?'Released to preview':'Not released','summary','green')+row('Follow-up actions','Record owner and review date','task-new','blue'))}</div></div>`);
add('video','Consultation room','Clinical workspace',['doctor','nurse','wellbeing'],()=>head('Consultation room','Secure video consultation.')+patientBar()+`<div class="grid"><div class="meeting"><div class="avatar">${p().initial}</div><h2>${p().name}</h2><small>Patient waiting · video consultation</small><div class="actions">${button('Microphone off','toggle-mic','secondary')}${button('Camera off','toggle-camera','secondary')}${link('End session',state.role==='wellbeing'?'wellbeing-session':'notes','danger')}</div></div>${card('During your consultation',banner('Confirm identity, current location, privacy and a callback plan before proceeding.')+detail([['Connection','Secure video'],['Recording','Not enabled'],['Patient contact',p().phone]])+link('Open notes',state.role==='wellbeing'?'wellbeing-session':'notes'))}</div>`);
add('notes','Consultation notes','Clinical workspace',['doctor','nurse','manager'],()=>clinicalTop('Consultation notes','Structured documentation, with accountable sign-off.',tag(r().signed?'Signed · locked':'Draft',r().signed?'green':'amber'))+(!['doctor','nurse'].includes(state.role)||r().signed?card('Signed / reviewed record',noteDisplay()+`<div class="actions">${r().signed&&['doctor','nurse'].includes(state.role)?link('Add an addendum','note-addendum'):''}${r().signed?link('Prepare patient summary','summary','','arrow'):''}</div>`):card('Clinical note',form('note-save',`<div class="fields">${area('Subjective · history and concerns','subjective',r().note.subjective)}${area('Objective · findings and observations','objective',r().note.objective)}</div><div class="fields">${area('Assessment · clinical reasoning','assessment',r().note.assessment)}${area('Plan · decisions and agreed actions','plan',r().note.plan)}</div>${area('Safety-netting and review arrangements','safety',r().note.safety)}${area('Consent, preferences and information shared','consent',r().note.consent)}${select('Patient visibility','share',['Patient summary only','Release full note after review'],r().note.share)}<p class="audit">Drafts are saved locally in this browser tab. Signing locks the note; later changes are recorded as addenda.</p>`,'Save draft and review','consultation'))));
function noteDisplay(){return Object.entries({subjective:'History and concerns',objective:'Findings',assessment:'Assessment',plan:'Plan',safety:'Safety-netting',consent:'Consent and preferences'}).map(([k,l])=>`<section class="clinical-note"><h3>${l}</h3><p class="note-text">${esc(r().note[k])}</p></section>`).join('')+`<p class="audit">${r().signed?'Signed by '+esc(r().signer)+' · '+esc(r().signedAt):'Unsigned draft · not a final clinical record'}</p>`+r().addenda.map(a=>`<div class="banner"><span><b>Addendum · ${esc(a.time)}</b><br>${esc(a.text)}<br><small>${esc(a.author)}</small></span></div>`).join('');}
add('note-review','Review & sign note','Clinical workspace',['doctor','nurse'],()=>clinicalTop('Review & sign','Check the complete record before signing.')+card('Consultation record',noteDisplay()+(r().signed?link('View signed note','notes'):form('note-sign',check('I have reviewed the findings, decisions, safety-netting and follow-up arrangements.','reviewed')+check('Sign this note as the selected professional.','sign'),'Sign note','notes'))));
