add('patient-app','Open connected patient app','Connected patient app',ALL,()=>head('Connected patient app','A separate patient-facing view of the same record.')+card('Open the patient view',`<p>Choose the patient below to view their released Health Records in a separate tab. Continue making changes in the professional portal, then refresh the patient view to see the update.</p><div class="actions">${PATIENTS.map((x,i)=>`<a class="btn secondary" href="/patient-app?patient=${i}" target="_blank" rel="noopener">${x.name}${ico('arrow')}</a>`).join('')}</div>`));
const nav=[['dashboard','Today’s overview','dashboard'],['schedule','Appointments','calendar'],['patients','Patients','people'],['consultation','Consultation','clinical'],['prescriptions','Prescribing','rx'],['tests','Tests & samples','lab'],['results','Results inbox','file'],['care','Professional care','care'],['wellbeing','Wellbeing','leaf'],['messages','Messages','message'],['tasks','Tasks & follow-up','task'],['governance','Clinical oversight','shield'],['team','Team & permissions','people'],['payments','Payment & cover','file'],['audit','Audit trail','log']];
function render(){let key=location.hash.slice(1)||'welcome';if(key==='welcome')key='dashboard';if(!routes[key])key='dashboard';current=allowed(key)?key:'access-denied';const page=routes[current];document.title=page.title+' · LifeCome Health';document.body.classList.toggle('board-mode',params.get('embed')==='1');document.body.style.fontSize=state.settings.text==='Larger'?'16px':'';document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard"><span class="lc-logo on-dark sm" role="img" aria-label="LifeCome Health"><img src="/brand/lifecome-health-mark.svg" alt="" width="34" height="32"><span class="lc-word"><b>Life</b><b>Come</b><b>Health</b></span></span><small>PROFESSIONAL PORTAL</small></a><div class="navlabel">Clinical workspace</div><nav>${nav.filter(([k])=>allowed(k)).map(([k,n,i])=>`<a href="#${k}" class="navlink ${current===k?'active':''}" ${current===k?'aria-current="page"':''}>${ico(i)}${n}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="navlink" href="#settings">${ico('settings')}Preferences</a><div class="profile-small"><span class="avatar">${who().initial}</span><span>${who().person}<small>${who().name}</small></span></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><div class="crumb">Workspace &nbsp; / &nbsp; <b>${page.group}</b></div><div class="top-actions"><span class="date sub" style="font-size:11px">${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short',year:'numeric',timeZone:'Europe/London'})}</span>${USER?.preview?`<a class="btn ghost" href="/admin/roles/${state.role}">Back to admin</a>`:''}<button class="btn ghost" data-action="signout">Sign out</button><a href="#tasks" aria-label="Tasks and notifications">${ico('bell')}</a><span class="avatar">${who().initial}</span></div></header><div class="content">${safeRender(page)}</div></main></div>`;window.scrollTo(0,0);save();}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3500);}
function navigate(k){dirty=false;formError='';location.hash=k;if(current===k)render();}
const FORM_ROLES={appointment:ALL,'cancel-appointment':ALL,consent:['doctor','nurse','care','wellbeing','manager'],observations:['doctor','nurse'],encounter:['doctor','nurse'],'note-save':['doctor','nurse'],'note-sign':['doctor','nurse'],'note-addendum':['doctor','nurse'],summary:['doctor','nurse'],'rx-draft':['doctor'],'rx-safety':['doctor'],'rx-authorise':['doctor'],'rx-cancel':['doctor'],'test-order':['doctor','nurse'],sample:['doctor','nurse'],'sample-repeat':CLIN,'result-review':CLIN,'result-release':CLIN,referral:['doctor'],'referral-send':['doctor'],'care-note':['care','nurse'],'wellbeing-note':['wellbeing'],message:ALL,task:ALL,incident:ALL,settings:ALL};
function handleForm(id,d){if(!FORM_ROLES[id]?.includes(state.role))throw Error('This role is not authorised for that action.');let next='dashboard',action='';
if(id==='appointment'){state.appointments.push({...d,patient:state.patient});next='schedule';action='Created appointment request';}
if(id==='cancel-appointment'){r().appointmentCancelled=true;next='schedule';action='Recorded appointment cancellation: '+d.reason;}
if(id==='consent'){r().consent={...d,time:now(),author:who().person};next='patient';action='Recorded consent decision';}
if(id==='observations'){r().observations={...d,time:d.time,author:who().person};next='patient';action='Recorded observations';}
if(id==='encounter'){r().encounter=d;next='notes';action='Completed encounter checks';}
if(id==='note-save'){if(r().signed)throw Error('Signed notes cannot be overwritten. Add an addendum.');r().note={...r().note,...d};next='note-review';action='Saved consultation draft';}
if(id==='note-sign'){if(r().signed)throw Error('This note is already signed.');if(!Object.values(r().note).every(Boolean))throw Error('Complete all required note sections.');r().signed=true;r().signedAt=now();r().signer=who().person;next='notes';action='Signed and locked consultation note';}
if(id==='note-addendum'){if(!r().signed)throw Error('An addendum requires a signed note.');r().addenda.push({text:d.text,time:now(),author:who().person});next='notes';action='Signed note addendum';}
if(id==='summary'){if(!r().signed)throw Error('Sign the note before releasing a summary.');r().summary=d.text;r().summaryFollowup=d.followup;r().summaryReleased=true;next='patient-preview';action='Released consultation summary to patient Health Records';}
if(id==='rx-draft'){r().rx={...d,author:who().person};r().rxStatus='Draft';r().rxSafety=false;next='rx-safety';action='Created prescription draft';}
if(id==='rx-safety'){if(!r().rx)throw Error('A prescription draft is required.');for(const x of ['scope','history','checks','consent','resolved'])if(!d[x])throw Error('Complete every safety attestation.');r().rxSafety=true;next='rx-authorise';action='Recorded prescribing safety review';}
if(id==='rx-authorise'){if(!r().rx||!r().rxSafety)throw Error('Complete the draft and safety review first.');r().rxStatus='Authorised';r().rx.authorisedAt=now();next='rx-status';action='Authorised prescription; updated patient record';}
if(id==='rx-cancel'){if(r().rxStatus!=='Authorised')throw Error('Only an authorised prescription can be cancelled.');r().rxStatus='Cancelled';r().rx.cancelReason=d.reason;next='rx-status';action='Cancelled prescription';}
if(id==='test-order'){r().order={...d,id:'DEMO-ORDER-'+p().id,time:now(),author:who().person};r().sample='Not collected';next='tests';action='Created test request with assigned reviewer';}
if(id==='sample'){if(!r().order)throw Error('Create a test request first.');r().sample=d.outcome;r().sampleRecord={...d,time:now(),author:who().person};next='sample-track';action='Updated sample collection status';}
if(id==='sample-repeat'){r().tasks.push({title:d.issue+': '+d.action,owner:'Clinical team',due:d.due});next='tasks';action='Created laboratory-exception follow-up';}
if(id==='result-review'){r().resultAction={...d,time:now(),author:who().person};r().resultReviewed=true;r().resultReleased=false;r().tasks.push({title:d.action,owner:who().person,due:d.due});next='result-release';action='Reviewed result and assigned follow-up; release pending';}
if(id==='result-release'){if(!r().resultReviewed)throw Error('Review the result before release.');r().resultReleased=true;next='patient-preview';action='Released reviewed result to patient Health Records';}
if(id==='referral'){r().referral={...d,author:who().person};r().referralSent=false;next='referral-review';action='Saved referral draft';}
if(id==='referral-send'){if(!r().referral)throw Error('Draft a referral first.');r().referralSent=true;next='referrals';action='Referral sent; updated patient record';}
if(id==='care-note'){r().careNote={...d,author:who().person,time:now()};next='patient-preview';action='Signed care visit and shared visit summary';}
if(id==='wellbeing-note'){r().wellbeingNote={...d,author:who().person,time:now()};if(d.concern==='Clinical review requested')r().tasks.push({title:'Review wellbeing clinical concern',owner:'Clinical team',due:'2026-11-10'});next='wellbeing-plan';action='Signed wellbeing session and shared agreed plan';}
if(id==='message'){r().messages.push({text:d.text,author:who().person,time:now()});next='messages';action='Added patient message';}
if(id==='task'){r().tasks.push({...d,time:now()});next='tasks';action='Created follow-up task';}
if(id==='incident'){r().incidents.push({...d,time:now(),author:who().person});next='dashboard';action='Recorded concern and responsible lead';}
if(id==='settings'){state.settings={channel:d.channel,text:d.text};next='settings';action='Updated workspace preferences';}
audit(action);syncPatientView();return next;}
function releasedRecord(i){const x=state.records[i];return {patient:PATIENTS[i],updatedAt:now(),consultation:x.summaryReleased?{summary:x.summary,followup:x.summaryFollowup,author:x.signer,signedAt:x.signedAt,fullNote:x.note.share==='Release full note after review'?{...x.note,addenda:x.addenda}:null}:null,observations:x.observations||null,prescription:x.rxStatus==='Authorised'?{...x.rx,status:x.rxStatus}:x.rxStatus==='Cancelled'?{status:'Cancelled'}:null,result:x.resultReleased?{explanation:x.resultAction.explanation,action:x.resultAction.action,due:x.resultAction.due,author:x.resultAction.author}:null,referral:x.referralSent?{specialty:x.referral.specialty,priority:x.referral.priority,status:'Sent — awaiting acknowledgement'}:null,care:x.careNote?{delivered:x.careNote.delivered,handover:x.careNote.handover,outcome:x.careNote.outcome,author:x.careNote.author,time:x.careNote.time}:null,wellbeing:x.wellbeingNote?{goal:x.wellbeingNote.goal,plan:x.wellbeingNote.plan,author:x.wellbeingNote.author,time:x.wellbeingNote.time}:null,messages:x.messages};}
function syncPatientView(){try{localStorage.setItem('lifecome-shared-patient-preview-v1',JSON.stringify({schemaVersion:'1.0',demoOnly:true,patients:PATIENTS.map((_,i)=>releasedRecord(i))}));}catch(_){}}
if(typeof window!=='undefined'&&!window.LC_TEST_MODE){
window.addEventListener('hashchange',()=>{formError='';render();});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('input',e=>{if(e.target.closest('form'))dirty=true;if(e.target.matches('[data-search-table]')){let q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));}if(e.target.matches('[data-search-screens]')){document.querySelectorAll('[data-screen-search]').forEach(el=>el.hidden=!el.dataset.screenSearch.includes(e.target.value.toLowerCase()));}});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){if(dirty&&!confirm('Discard unsaved changes?')){e.target.value=state.role;return;}state.role=e.target.value;if(state.role==='care')state.patient=2;dirty=false;save();navigate('dashboard');render();}});
document.addEventListener('click',e=>{let el=e.target.closest('a,button');if(!el)return;
if(el.dataset.role){state.role=el.dataset.role;if(state.role==='care')state.patient=2;save();navigate('dashboard');return;}
if(el.dataset.patient!==undefined){state.patient=Number(el.dataset.patient);save();navigate(el.dataset.target||'patient');return;}
if(el.dataset.screenRole){state.role=el.dataset.screenRole;save();}
if(el.getAttribute('href')?.startsWith('#')&&dirty){if(!confirm('Discard unsaved changes?')){e.preventDefault();return;}dirty=false;}
let a=el.dataset.action;if(!a)return;if(a==='signout'){fetch('/api/auth/logout',{method:'POST'}).finally(()=>location.assign('/'));return;}if(a==='menu'){document.getElementById('sidebar').classList.toggle('open');return;}if(a==='reset'){if(!confirm('Reset all records and activity?'))return;state=defaults();dirty=false;save();syncPatientView();navigate('dashboard');render();return;}if(a==='task-done'){state.taskDone=true;audit('Completed follow-up task');render();}if(a==='arrived'){r().arrived=true;audit('Marked patient arrived');toast('Arrival recorded.');}if(a==='toggle-mic'||a==='toggle-camera'){el.textContent=el.textContent.includes('off')?el.textContent.replace('off','on'):el.textContent.replace('on','off');} });
document.addEventListener('submit',e=>{let f=e.target;if(!f.dataset.form)return;e.preventDefault();if(!f.reportValidity())return;try{let next=handleForm(f.dataset.form,Object.fromEntries(new FormData(f)));dirty=false;formError='';save();navigate(next);render();toast('Record updated.');}catch(err){formError=err.message;let old=f.querySelector('.formerror');if(old)old.remove();f.insertAdjacentHTML('afterbegin',`<div class="formerror" role="alert">${esc(formError)}</div>`);}});
syncPatientView();render();}

// Cross-app record bridge.
const PATIENT_APP_URL = window.LIFECOME_CONFIG?.patientAppUrl || 'http://localhost:3000/patient/';
const PATIENT_APP_ORIGIN = new URL(PATIENT_APP_URL).origin;
let patientWindow=null,linkedPatient=0;
function pushPatientRecord(){if(patientWindow&&!patientWindow.closed)patientWindow.postMessage({type:'LIFECOME_RECORD_UPDATE',schemaVersion:'1.0',demoOnly:true,record:releasedRecord(linkedPatient)},PATIENT_APP_ORIGIN);}
const originalSyncPatientView=syncPatientView;
syncPatientView=function(){originalSyncPatientView();pushPatientRecord();};
if(typeof window!=='undefined'&&!window.LC_TEST_MODE){
window.addEventListener('message',e=>{if(e.origin!==PATIENT_APP_ORIGIN||e.source!==patientWindow)return;if(e.data?.type==='LIFECOME_PATIENT_READY')pushPatientRecord();if(e.data?.type==='LIFECOME_RECORD_RECEIVED')toast('Patient app Health Records updated for '+PATIENTS[linkedPatient].name+'.');});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="open-patient-app"],[data-action="download-record"]');if(!b)return;linkedPatient=state.patient;if(b.dataset.action==='open-patient-app'){patientWindow=window.open(PATIENT_APP_URL+'#professional-records','LifeComePatientRecords');if(!patientWindow)toast('Allow the patient-app window, or use the record export below.');else setTimeout(pushPatientRecord,1200);}else{const data={type:'LIFECOME_RECORD_UPDATE',schemaVersion:'1.0',demoOnly:true,record:releasedRecord(state.patient)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=p().id+'-released-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}});
}
const patientAppOriginal=routes['patient-app'].render;
routes['patient-app'].render=()=>head('Update the patient app','Release records here, then view them in the LifeCome patient app.')+patientBar()+card('Existing patient app · connected Health Records',`<p>Open the patient app for <b>${p().name}</b>. Released notes, prescriptions, results, referrals, observations and plans are transferred to its Health Records screen. Keep that window open to see subsequent updates.</p><div class="actions">${button('Open existing patient app','open-patient-app','','')}${button('Export released record','download-record','secondary')}</div><p class="audit">If your browser blocks the connection, import the exported record on the patient app’s Professional updates screen.</p>`)+card('Local companion view',`<p class="sub">The companion preview also updates automatically on this browser.</p><a class="btn secondary" href="/patient-app?patient=${state.patient}" target="_blank" rel="noopener">Open companion patient view ${ico('arrow')}</a>`);
if(typeof window!=='undefined'&&!window.LC_TEST_MODE&&current==='patient-app')render();
